def accounts_for_existing_lines(apps, schema_editor):
    """Decision 2026-11-17: one account per client per country. Every existing escrow becomes a line of its
    client's account: held funds become the free balance, every other escrow a commitment. The account's pay-in
    reference is the one the bank already issued for the held amount in the country's own currency. No bank fact
    is touched: balances stay derived from the bank's events (ADR-18, ADR-26)."""
    import secrets

    Escrow = apps.get_model("escrow", "Escrow")
    ClientAccount = apps.get_model("escrow", "ClientAccount")
    Country = apps.get_model("countries", "Country")
    pairs = Escrow.objects.order_by().values_list("client_id", "country_id").distinct()
    for client_id, country_id in pairs:
        country = Country.objects.get(pk=country_id)
        lines = Escrow.objects.filter(client_id=client_id, country_id=country_id).order_by("created_at")
        first = lines.first()
        held = lines.filter(kind="held_funds", currency=country.currency, virtual_account_ref__isnull=False).first()
        acc = ClientAccount.objects.create(
            country_id=country_id, client_id=client_id, bank_partner_id=first.bank_partner_id,
            reference=f"ACC-{country.code}-{secrets.token_hex(4).upper()}", created_by_id=first.created_by_id,
            virtual_account_ref=held.virtual_account_ref if held else None)
        lines.update(account=acc)


